def encode_cursor(row: ActivityRow) -> str:
    """Return an opaque cursor representing ``row``'s pagination key."""
    value = json.dumps(
        {"created_at": row.created_at.isoformat(), "id": row.id},
        separators=(",", ":"),
        ensure_ascii=False,
    ).encode("utf-8")
    return base64.urlsafe_b64encode(value).decode("ascii")


def decode_cursor(cursor: str) -> tuple[datetime, str]:
    """Decode a cursor or raise ``ValueError`` when it is malformed."""
    try:
        if not isinstance(cursor, str) or not cursor:
            raise ValueError
        if any(char not in "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_=" for char in cursor):
