        raw = base64.b64decode(cursor.encode("ascii"), altchars=b"-_", validate=True)
        value = json.loads(raw.decode("utf-8"))
        if not isinstance(value, dict) or set(value) != {"created_at", "id"}:
            raise ValueError
        timestamp = value["created_at"]
        identifier = value["id"]
        if not isinstance(timestamp, str) or not isinstance(identifier, str):
            raise ValueError
        if timestamp.endswith("Z"):
            timestamp = timestamp[:-1] + "+00:00"
        return datetime.fromisoformat(timestamp), identifier
    except (ValueError, TypeError, KeyError, json.JSONDecodeError,
            UnicodeDecodeError, UnicodeEncodeError, binascii.Error):
        raise ValueError("malformed cursor") from None


