{"pagination_py":""""Activity-feed pagination API."""

from __future__ import annotations

import base64
import json
from collections.abc import Sequence
from dataclasses import dataclass
from datetime import datetime
from typing import Any


@dataclass(frozen=True, slots=True)
class ActivityRow:
    """One activity-feed row."""

    created_at: datetime
    id: str
    payload: Any = None


def encode_cursor(row: ActivityRow) -> str:
    """Return an opaque cursor representing ``row``'s pagination key."""
    try:
        raw = json.dumps(
            [row.created_at.isoformat(), row.id],
            ensure_ascii=False,
            separators=(",", ":"),
        ).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")
    except (AttributeError, TypeError, ValueError) as exc:
        raise ValueError("invalid row pagination key") from exc


def decode_cursor(cursor: str) -> tuple[datetime, str]:
    """Decode a cursor or raise ``ValueError`` when it is malformed."""
    if not isinstance(cursor, str) or not cursor:
        raise ValueError("malformed cursor")
    try:
        if any(ch not in "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_" for ch in cursor):
            raise ValueError
        padded = cursor + "=" * (-len(cursor) % 4)
        value = json.loads(base64.urlsafe_b64decode(padded).decode("utf-8"))
        if not isinstance(value, list) or len(value) != 2:
            raise ValueError
        timestamp, row_id = value
        if not isinstance(timestamp, str) or not isinstance(row_id, str):
            raise ValueError
        return datetime.fromisoformat(timestamp), row_id
    except (ValueError, TypeError, UnicodeError, json.JSONDecodeError) as exc:
        raise ValueError("malformed cursor") from exc


def page_after(
    rows: Sequence[ActivityRow],
    cursor: str | None,
    limit: int,
) -> tuple[list[ActivityRow], str | None]:
    """Return the next ascending page and a cursor when more rows remain."""
    if not isinstance(limit, int) or isinstance(limit, bool) or limit <= 0:
        raise ValueError("limit must be positive")

    boundary = decode_cursor(cursor) if cursor is not None else None
    ordered = sorted(rows, key=lambda row: (row.created_at, row.id))
    if boundary is not None:
        ordered = [
            row for row in ordered
            if (row.created_at, row.id) > boundary
        ]

    page = ordered[:limit]
    if len(ordered) > len(page):
        return page, encode_cursor(page[-1])
    return page, None
